module.exports = {
  inspect() {
    return {
      diagnostics: [
        {
          severity: "info",
          code: "plugin-inspected",
          message: "Node.js pnpm plugin inspected the repo."
        }
      ],
      details: {
        plugin: "@envheaven/plugin-nodejs-pnpm"
      }
    };
  },
  async execute(plan) {
    return {
      exitCode: 0,
      details: {
        executedTarget: plan.requestedTarget,
        resolvedTarget: plan.resolvedTarget
      }
    };
  }
};
